#!/usr/bin/env node
/* tools/build-bundles.js — flagship readiness J (D-40)

   A first visit to a workout page made 43–49 script requests. 24 of them are
   the same shared modules, in the same order, on most of the 79 workout
   pages. This writes those runs out as two committed files
   (tools/bundles.json says which) and swaps each run for one <script> tag.

   Not a build step: there is still no bundler and no package.json. The
   bundles are committed, the members stay the source, and --check fails CI
   when a bundle no longer matches its members or a page still carries a run
   it could load as one file. Same shape as build-sw.py.

   Measured with tools/measure-first-visit.js (HTTP/2 + gzip, Slow 3G): see
   flagship-readiness-roadmap.md's J section for the before/after table.

   What the bundle does to each member, and why:
     * Each member is wrapped in its own try/catch. As separate files, one
       module throwing at load stopped only that module; concatenated, it
       would stop every module after it. The catch re-throws on a timer,
       with the member's name on the message, so it still reaches the
       head-boot error log (mc_errors_v1) and the error beacon.
     * Wrapping is only safe for a member with NO top-level declaration: a
       `function`, `const`, `let` or `class` inside a try block is scoped to
       that block, so a global another file reads would vanish. Every member
       today is a single IIFE (or one `window.X = …` assignment). This script
       refuses to bundle a member that grows a top-level declaration or a
       file-level 'use strict' (a directive stops being one inside a block).
     * A page is rewritten only where the members appear CONTIGUOUSLY and IN
       ORDER, so no module runs earlier or later relative to anything else
       on that page. Pages that interleave another script inside the run keep
       their separate tags; they are reported, not forced.

   usage: node tools/build-bundles.js            # write bundles + rewrite pages
          node tools/build-bundles.js --check    # CI: exit 1 if anything is stale
*/
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const CONF = JSON.parse(fs.readFileSync(path.join(__dirname, 'bundles.json'), 'utf8')).bundles;
const CHECK = process.argv.includes('--check');

// Depth-0 text of a script with comments, strings, templates and regex
// literals removed: enough to see what a file declares at top level.
function topLevel(src) {
  let out = '', i = 0, depth = 0, prev = '';
  const n = src.length;
  const regexOK = () => /(^|[(,=:\[!&|?{};+\-*%<>~^]|\breturn|\btypeof|\bcase|\bdo|\belse|\bin|\bof|\bnew|\bdelete|\bvoid|\bthrow)\s*$/.test(prev);
  while (i < n) {
    const c = src[i], d = src[i + 1];
    if (c === '/' && d === '/') { while (i < n && src[i] !== '\n') i++; continue; }
    if (c === '/' && d === '*') { const e = src.indexOf('*/', i + 2); i = e < 0 ? n : e + 2; continue; }
    if (c === '"' || c === "'") { i++; while (i < n && src[i] !== c) { if (src[i] === '\\') i++; i++; } i++; prev += 's'; continue; }
    if (c === '`') {
      i++; let td = 0;
      while (i < n) {
        if (src[i] === '\\') { i += 2; continue; }
        if (src[i] === '`' && td === 0) break;
        if (src[i] === '$' && src[i + 1] === '{') { td++; i += 2; continue; }
        if (src[i] === '}' && td > 0) { td--; i++; continue; }
        i++;
      }
      i++; prev += 's'; continue;
    }
    if (c === '/' && regexOK()) {
      i++; let cls = false;
      while (i < n) {
        if (src[i] === '\\') { i += 2; continue; }
        if (src[i] === '[') cls = true; else if (src[i] === ']') cls = false;
        else if (src[i] === '/' && !cls) break;
        i++;
      }
      i++; while (/[a-z]/i.test(src[i] || '')) i++; prev += 'r'; continue;
    }
    if (c === '{' || c === '(' || c === '[') { if (depth === 0) out += c; depth++; }
    else if (c === '}' || c === ')' || c === ']') { depth--; if (depth === 0) out += c; }
    else if (depth === 0) out += c;
    prev = /\s/.test(c) ? prev + ' ' : (prev + c).slice(-12);
    i++;
  }
  return out;
}

function unsafe(file, src) {
  const top = topLevel(src);
  const decl = top.match(/\b(function|const|let|class)\b/);
  if (decl) return 'declares `' + decl[1] + '` at top level';
  if (/^\s*(['"])use strict\1/.test(top)) return "has a file-level 'use strict'";
  return null;
}

function buildBundle(name, members) {
  const problems = [];
  const head = [
    '/* GENERATED by tools/build-bundles.js from tools/bundles.json — do not edit.',
    '   Edit the member files and run `node tools/build-bundles.js`.',
    '   Flagship readiness J (D-40): ' + members.length + ' shared modules in one request.',
    '   Members, in load order (line numbers are in this file):'
  ];
  const parts = [];
  for (const m of members) {
    const src = fs.readFileSync(path.join(ROOT, m), 'utf8');
    const why = unsafe(m, src);
    if (why) problems.push(name + ': ' + m + ' ' + why + ', so it cannot be wrapped safely');
    parts.push({ m, body: src.replace(/\s+$/, '') });
  }
  // two passes: the header lists each member's first line, which depends on
  // the header's own length
  const lineOf = [];
  let text = '';
  for (let pass = 0; pass < 2; pass++) {
    const hdr = head.concat(members.map((m, k) => '     ' + m + (lineOf[k] ? ' @ line ' + lineOf[k] : ''))).join('\n') + '\n*/\n';
    let line = hdr.split('\n').length;
    let body = '';
    parts.forEach((p, k) => {
      const open = '\n/* ---- ' + p.m + ' ---- */\ntry {\n';
      line += 3;
      lineOf[k] = line;
      const close = '\n} catch (e) { try { e.message = "[' + p.m + '] " + e.message; } catch (_) {} setTimeout(function () { throw e; }); }\n';
      body += open + p.body + close;
      line += p.body.split('\n').length + 1;
    });
    text = hdr + body;
  }
  return { text, problems };
}

function tagRe(file) {
  return '<script src="' + file.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '"></script>';
}
// Between two members only whitespace and HTML comments may sit. The
// comments (several explain why a tag is on that page) are kept, moved above
// the bundle tag in their original order.
const GAP = '(?:\\s|<!--[\\s\\S]*?-->)*';
function runRe(members) {
  return new RegExp(members.map(tagRe).join(GAP));
}
function collapse(match, name) {
  const notes = match.match(/<!--[\s\S]*?-->/g) || [];
  return notes.map((c) => c + '\n').join('') + '<script src="' + name + '"></script>';
}

const problems = [];
const report = [];
const pages = fs.readdirSync(ROOT).filter((f) => f.endsWith('.html') && !f.endsWith('.dc.html')).sort();

for (const [name, members] of Object.entries(CONF)) {
  const { text, problems: p } = buildBundle(name, members);
  problems.push(...p);
  const out = path.join(ROOT, name);
  const cur = fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : null;
  if (cur !== text) {
    if (CHECK) problems.push(name + ' is stale — run `node tools/build-bundles.js`');
    else if (!p.length) fs.writeFileSync(out, text);
  }
}

for (const page of pages) {
  const file = path.join(ROOT, page);
  let html = fs.readFileSync(file, 'utf8');
  const before = html;
  for (const [name, members] of Object.entries(CONF)) {
    const rx = runRe(members);
    if (rx.test(html)) {
      if (CHECK) problems.push(page + ' carries the whole ' + name + ' run as separate tags — run `node tools/build-bundles.js`');
      html = html.replace(rx, (m) => collapse(m, name));
    }
    if (html.includes('<script src="' + name + '"></script>')) {
      const twice = members.filter((m) => html.includes('<script src="' + m + '"'));
      if (twice.length) problems.push(page + ' loads ' + name + ' and also ' + twice.join(', ') + ' — those members would run twice');
      report.push(name);
    }
  }
  if (!CHECK && html !== before) fs.writeFileSync(file, html);
}

const counts = {};
report.forEach((n) => { counts[n] = (counts[n] || 0) + 1; });
for (const [name, members] of Object.entries(CONF)) {
  // pages that load every member but not as the bundle: interleaved runs
  const partial = pages.filter((pg) => {
    const h = fs.readFileSync(path.join(ROOT, pg), 'utf8');
    return !h.includes('<script src="' + name + '"></script>') &&
      members.every((m) => h.includes('<script src="' + m + '"'));
  });
  console.log(name + ': ' + members.length + ' modules, loaded by ' + (counts[name] || 0) + ' pages' +
    (partial.length ? '; ' + partial.length + ' more load every member with something interleaved, and keep separate tags' : ''));
}
if (problems.length) {
  problems.forEach((p) => console.error('::error::' + p));
  process.exit(1);
}
console.log(CHECK ? 'bundles up to date' : 'bundles written');
